91: // pwr
92: inline double pwr(double base, int exp) {
93:   double res = 1.0;
94:   long long p = exp;
95:   if (p < 0) {
96:     base = 1.0 / base;
97:     p = -p;
98:   }
99:   while (p > 0) {
100:     if (p & 1)
101:       res *= base;
102:     base *= base;
103:     p >>= 1;
104:   }
105:   return res;
106: }
