191: template <typename T> double divi(const vector<T> &v) {
192:   if (v.empty())
193:     return 0.0;
194:   double res = static_cast<double>(v[0]);
195:   for (size_t i = 1; i < v.size(); ++i) {
196:     if (v[i] == 0) {
197:       cout << "Division of 0 --> Invalid" << endl;
198:       return 0.0;
199:     }
200:     res /= v[i];
201:   }
202:   return res;
203: }
