#include "../main.h"

main {
  detach_C();

  out << "====================================================\n";
  out << "  Sample 1: Basic Custom Loops & Helper Functions   \n";
  out << "====================================================\n\n";

  // 1. Forward Exclusive Loop: loop(var, start, end, step) -> [0, 5)
  out << "[1] Forward Exclusive: loop(i, 0, 5, i++)\n";
  out << "    Values: ";
  loop(i, 0, 5, i++) {
    out << i << " ";
  }
  out << "\n\n";

  // 2. Forward Inclusive Loop: loop2(var, start, end, step) -> [1, 5]
  out << "[2] Forward Inclusive: loop2(i, 1, 5, i++)\n";
  out << "    Values and Properties:\n";
  loop2(i, 1, 5, i++) {
    out << "    - i = " << i
        << " | sqr = " << sqr(i)
        << " | cube = " << cube(i)
        << " | " << (is_even(i) ? "EVEN" : "ODD")
        << "\n";
  }
  out << "\n";

  // 3. Reverse Exclusive Loop: loopr(var, start, end, step) -> (5, 0]
  out << "[3] Reverse Exclusive: loopr(i, 5, 0, i--)\n";
  out << "    Values: ";
  loopr(i, 5, 0, i--) {
    out << i << " ";
  }
  out << "\n\n";

  // 4. Reverse Inclusive Loop: loop2r(var, start, end, step) -> [5, 0]
  out << "[4] Reverse Inclusive: loop2r(i, 5, 0, i--)\n";
  out << "    Values: ";
  loop2r(i, 5, 0, i--) {
    out << i << " ";
  }
  out << "\n";
  out << "====================================================\n";

  return 0;
}

/*
================================================================================
Theory Summary & Algorithmic Notes (Ref: doc/Assignments/learning/A4_theory.md)
================================================================================
- Problem: Demonstration of custom preprocessor-defined loop syntax and
  integrated type-generic helper functions within the b1t_Lang DSL.
- Technique:
  1. Token Replacement Loops:
     - loop(var, s, e, step)  -> for (int var = (s); (var) < (e); (step))
     - loop2(var, s, e, step) -> for (int var = (s); (var) <= (e); (step))
     - loopr(var, s, e, step) -> for (int var = (s); (var) > (e); (step))
     - loop2r(var, s, e, step)-> for (int var = (s); (var) >= (e); (step))
  2. Type-Generic Arithmetic Helpers: sqr(i), cube(i), is_even(i), is_odd(i).
  3. Stream Aliasing: Utilizing 'out' and 'detach_C()' for fast, safe I/O.
- Complexity:
  * Time: O(N) linear iteration across bounded loop ranges.
  * Space: O(1) auxiliary stack memory.
- Edge Cases & Safety:
  * Parenthesized macro arguments prevent precedence hijacking: (var) < (end).
  * Strict loop bounds prevent off-by-one boundary overruns.
================================================================================
*/

#include "../main.h"

main {
  detach_C();

  out << "====================================================\n";
  out << " Sample 2: Mathematical Series & Vector Reductions  \n";
  out << "====================================================\n\n";

  int n = 6;
  vector<int> numbers;
  long long iterative_sum = 0;

  out << "Iterating from 1 to " << n << " and gathering statistics:\n";
  loop2(i, 1, n, i++) {
    numbers.push_back(i);
    iterative_sum = sum(iterative_sum, i); // Variadic sum(a, b)

    out << "  Step " << i << ":"
        << " fact(" << i << ") = " << fact(i)
        << " | pwr(2, " << i << ") = " << pwr(2, i)
        << " | running sum = " << iterative_sum
        << "\n";
  }

  out << "\n--- Vector Template Reductions ---\n";
  out << "Vector Elements   : ";
  loop(idx, 0, static_cast<int>(numbers.size()), idx++) {
    out << numbers[idx] << " ";
  }
  out << "\n";

  // Vector reductions defined in main.h
  out << "Vector Sum (sum(v))     : " << sum(numbers) << "\n";
  out << "Gauss Formula sum_n(" << n << ") : " << sum_n(n) << "\n";
  out << "Verification (is_eq)    : "
      << (is_eq(sum(numbers), sum_n(n)) ? "MATCH" : "MISMATCH") << "\n";
  out << "Vector Max (mx(v))      : " << mx(numbers) << "\n";
  out << "Vector Min (mn(v))      : " << mn(numbers) << "\n";
  out << "Vector Product (mul(v)) : " << mul(numbers) << "\n";

  out << "====================================================\n";

  return 0;
}

/*
================================================================================
Theory Summary & Algorithmic Notes (Ref: doc/Assignments/learning/A4_theory.md)
================================================================================
- Problem: Accumulate mathematical sequences using b1t_Lang loops and compare
  scalar fold reductions against dynamic vector overloads.
- Technique:
  1. Forward Inclusive Loop: loop2(i, 1, n, i++) for [1, N] sequence progression.
  2. Iterative Function Calls: fact(i), pwr(2, i), and variadic sum(acc, x).
  3. Dynamic Vector Overload Resolution: Automatic dispatch to container-based
     sum(const vector<T>&), mx(const vector<T>&), and mul(const vector<T>&).
  4. Closed-form Validation: Cross-verifying loop sum against sum_n(n) via is_eq.
- Complexity:
  * Time: O(N) linear iteration for vector collection and reductions.
  * Space: O(N) dynamic storage for vector elements.
- Edge Cases & Safety:
  * Safe exponentiation handling in pwr() via binary exponentiation.
  * Safe boundary checks preventing out-of-bounds in vector reductions.
================================================================================
*/

#include "../main.h"

main {
  detach_C();

  out << "====================================================\n";
  out << " Sample 3: Nested Loops & Multiplication Matrix     \n";
  out << "====================================================\n\n";

  int size = 5;

  out << "Multiplication Grid (" << size << "x" << size << "):\n\n";

  // Header row
  out << "   * |";
  loop2(col, 1, size, col++) {
    out << "   " << col;
  }
  out << "\n-----+";
  loop2(col, 1, size, col++) {
    out << "----";
  }
  out << "\n";

  // Nested loop traversal: Outer loop represents rows, inner loop represents columns
  loop2(row, 1, size, row++) {
    out << "   " << row << " |";
    loop2(col, 1, size, col++) {
      int product = mul(row, col);

      // Highlight diagonal elements using is_eq helper
      if (is_eq(row, col)) {
        // Diagonal element (square)
        out << " [" << (product < 10 ? " " : "") << product << "]";
      } else {
        out << "  " << (product < 10 ? " " : "") << product << " ";
      }
    }
    out << "\n";
  }

  out << "\nLegend: [x] denotes main diagonal squares (row == col).\n";
  out << "====================================================\n";

  return 0;
}

/*
================================================================================
Theory Summary & Algorithmic Notes (Ref: doc/Assignments/learning/A4_theory.md)
================================================================================
- Problem: Construct 2D arithmetic multiplication grid using nested custom
  preprocessor loop constructs and b1t_Lang mathematical helpers.
- Technique:
  1. Nested Macro Loops: loop2(row, 1, size, row++) nesting loop2(col, 1, size, col++).
  2. Variadic Multiplication: mul(row, col) evaluating product.
  3. Diagonal Matrix Identification: is_eq(row, col) identifying perfect squares.
- Complexity:
  * Time: O(R * C) where R = rows, C = columns.
  * Space: O(1) auxiliary stack space.
- Edge Cases & Safety:
  * Proper identifier scoping across nested loop variables (row vs col).
  * Safe formatted spacing for single vs double-digit values.
================================================================================
*/

