)

$nl = [System.Environment]::NewLine
$lines = Get-Content -LiteralPath $transcriptPath -Encoding UTF8

$turnTitles = @{
    1 = "Overview of C++ Templates in main.h"
    2 = "Deep Dive into divide_one Lambda (Lines 49–55)"
    3 = "Deep Dive into mx Variadic constexpr Template (Lines 66–72)"
    4 = "Sample Codes in Project.Compiler/sample/"
    5 = "Full Chat Archive Standard Update across AGENTS.md"
}

$turns = @()
$currentTurn = $null

foreach ($line in $lines) {
    if ([string]::IsNullOrWhiteSpace($line)) { continue }
    $step = $line | ConvertFrom-Json

    if ($step.type -eq "USER_INPUT") {
        if ($currentTurn) {
            $turns += $currentTurn
        }
        $currentTurn = [PSCustomObject]@{
            turnNumber = $turns.Count + 1
            userInput = $step.content
            thinking = @()
            response = ""
        }
    } elseif ($step.type -eq "PLANNER_RESPONSE") {
        if ($step.thinking -and -not [string]::IsNullOrWhiteSpace($step.thinking)) {
            $currentTurn.thinking += $step.thinking.Trim()
        }
        if ($step.content -and -not [string]::IsNullOrWhiteSpace($step.content)) {
            $currentTurn.response = $step.content.Trim()
        }
    }
}
if ($currentTurn) {
    $turns += $currentTurn
}

$sb = [System.Text.StringBuilder]::new()
$null = $sb.AppendLine('# 23. Template Usage in Project.Compiler/main.h')
$null = $sb.AppendLine('')
$null = $sb.AppendLine('- **Conversation ID**: `922619d1-7d3e-46cd-8689-abf3f29b9bce`')
