    $anchor = "turn-$num-" + (($title.ToLower() -replace '[^a-z0-9]+', '-') -replace '-$', '')
    $null = $sb.AppendLine("- [Turn $num: $title](#$anchor)")
}
$null = $sb.AppendLine('')
$null = $sb.AppendLine('---')
$null = $sb.AppendLine('')

foreach ($t in $turns) {
    $num = $t.turnNumber
    $title = if ($turnTitles.ContainsKey($num)) { $turnTitles[$num] } else { "Turn $num Discussion" }

    $null = $sb.AppendLine("## Turn $num: $title")
