        $null = $sb.AppendLine('<details>')
        $null = $sb.AppendLine('<summary>Click to expand internal reasoning</summary>')
        $null = $sb.AppendLine('')
        foreach ($th in $t.thinking) {
            $null = $sb.AppendLine($th)
            $null = $sb.AppendLine('')
        }
        $null = $sb.AppendLine('</details>')
        $null = $sb.AppendLine('')
    }

    if (-not [string]::IsNullOrWhiteSpace($t.response)) {
        $null = $sb.AppendLine('### 🤖 Assistant Response')
        $null = $sb.AppendLine('')
        $null = $sb.AppendLine($t.response)
        $null = $sb.AppendLine('')
        $null = $sb.AppendLine('---')
        $null = $sb.AppendLine('')
    } elseif ($num -eq $turns.Count -and -not [string]::IsNullOrWhiteSpace($pendingResponse)) {
